@theme {
  /* used via utility-classes, bg-background, text-primary, and many more */
  --color-background: #FAFAF7;
  --color-foreground: #1A1A1A;
  --color-border: #E8E3DC;
  --color-input: #F3EFE9;
  --color-primary: #F26522;
  --color-primary-foreground: #ffffff;
  --color-secondary: #FDE8D8;
  --color-secondary-foreground: #F26522;
  --color-coral: #F4845F;
  --color-coral-foreground: #ffffff;
  --color-muted: #EDE8E2;
  --color-muted-foreground: #8C8782;
  --color-success: #22C55E;
  --color-success-foreground: #ffffff;
  --color-card: #FFFFFF;
  --color-card-foreground: #1A1A1A;
  --color-surface: #F7F3EE;

  /* DO NOT REMOVE: these radius variables are required by the theme editor. */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 32px;

  /* DONT CHANGE OR REMOVE THIS VARIABLE */
  --radius: var(--radius-sm);

  /* DO NOT REMOVE: these font variables are required by the theme editor. */
  /* available fonts: "Inter", "DM Sans", "Nunito", "PT Serif", "Space Grotesk", "IBM Plex Mono", "IBM Plex Sans", "Roboto Slab", "Geist", "Shantell Sans" */
  --font-body: DM Sans;
  --font-headings: DM Sans;

  /* Add and change text sizes as you see fit */
  --text-xs: 11px;
  --text-sm: 13px;
  --text-base: 15px;
  --text-lg: 17px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 38px;
  --text-5xl: 52px;
}

import Icon from '@global/Icon';

export const displayName = 'Mobile Bottom Nav';
export const shortDescription = 'Fixed bottom navigation bar for mobile screens';

const items = [
  { icon: 'home', label: t('Accueil'), active: true },
  { icon: 'compass', label: t('Découvrir'), active: false },
  { icon: 'plus', label: t('Créer'), active: false, isCenter: true },
  { icon: 'music', label: t('Mes chansons'), active: false },
  { icon: 'zap', label: t('Crédits'), badge: '3', active: false },
];

export default function MobileBottomNav({ activeTab = 'Accueil' }) {
  return (
    <div className="bg-card border border-border rounded-xl mx-4 mb-4 px-2 py-2 flex items-center justify-around"
      style={{ boxShadow: '0 4px 24px rgba(0,0,0,0.10)' }}>
      {items.map((item) => {
        const isActive = item.label === activeTab;
        if (item.isCenter) {
          return (
            <button key={item.label} className="flex flex-col items-center justify-center -mt-6">
              <div className="bg-primary w-14 h-14 rounded-xl flex items-center justify-center"
                style={{ boxShadow: '0 4px 16px rgba(242,101,34,0.40)' }}>
                <Icon i="plus" size={28} className="text-primary-foreground" />
              </div>
            </button>
          );
        }
        return (
          <button key={item.label} className="flex flex-col items-center gap-0.5 px-2 py-1 relative">
            <Icon i={item.icon} size={22} className={isActive ? 'text-primary' : 'text-muted-foreground'} />
            {item.badge && (
              <div className="absolute -top-1 -right-1 bg-primary text-primary-foreground text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center">
                {item.badge}
              </div>
            )}
            <span className={`text-xs font-body ${isActive ? 'text-primary font-semibold' : 'text-muted-foreground'}`}>{item.label}</span>
          </button>
        );
      })}
    </div>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Song Card';
export const shortDescription = 'A card showing a user song with play controls';

export default function SongCard({ title = 'Pour toi Mariam', style = 'Afrobeat', occasion = 'Anniversaire', versions = 2, plays = 1240, likes = 87 }) {
  return (
    <div className="bg-card rounded-lg border border-border p-4 flex items-center gap-3"
      style={{ boxShadow: '0 1px 8px rgba(0,0,0,0.06)' }}>
      <div className="w-12 h-12 bg-secondary rounded-lg flex items-center justify-center flex-shrink-0">
        <Icon i="music-2" size={22} className="text-primary" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-semibold text-base text-foreground truncate">{title}</p>
        <div className="flex items-center gap-2 mt-0.5">
          <span className="text-xs text-muted-foreground">{style}</span>
          <span className="text-xs text-muted-foreground">·</span>
          <span className="text-xs text-muted-foreground">{occasion}</span>
        </div>
        <div className="flex items-center gap-3 mt-1">
          <span className="text-xs text-muted-foreground flex items-center gap-1">
            <Icon i="layers" size={11} /> {versions} {t('versions')}
          </span>
          <span className="text-xs text-muted-foreground flex items-center gap-1">
            <Icon i="headphones" size={11} /> {plays}
          </span>
          <span className="text-xs text-muted-foreground flex items-center gap-1">
            <Icon i="heart" size={11} /> {likes}
          </span>
        </div>
      </div>
      <button className="w-10 h-10 bg-primary rounded-lg flex items-center justify-center flex-shrink-0">
        <Icon i="play" size={16} className="text-primary-foreground" />
      </button>
    </div>
  );
}
